import type { Theme } from '@docshunt/docs-editor-wasm';
import { z } from 'zod';

import type {
  StartFunnelSession,
  StartStepKey
} from '@/routes/_authenticated/start/-startFlow.types';

const publicIdSchema = z.union([z.string(), z.number()]).transform(String);
const themeSchema = z.custom<Theme>(() => true);

const draftPromptProfileSchema = z.enum([
  'business_plan',
  'rnd_plan',
  'everyone_startup'
]);
const startPromptModeSchema = z.enum(['idea', 'aiReviewer']);
const startStepSchema = z.enum([
  'template',
  'prompt',
  'upload',
  'visual-suggestions',
  'settings',
  'generate'
]);

const selectedDraftTemplateSchema = z.object({
  id: publicIdSchema,
  name: z.string(),
  promptProfile: draftPromptProfileSchema,
  displayOrder: z.number().int().optional(),
  isFreeDraftTemplate: z.boolean().optional()
});

const promptStateSchema = z.object({
  activeTab: startPromptModeSchema,
  ideaText: z.string(),
  aiAnswers: z.record(z.string(), z.string())
});

const selectedDocumentSchema = z.object({
  type: z.enum(['export', 'draftProduct', 'draftExport']),
  id: publicIdSchema,
  productContents: z.string()
});

const imageItemSchema = z.object({
  title: z.string(),
  prompt: z.string(),
  position: z.string(),
  genBy: z.enum(['ai', 'human']),
  checked: z.boolean()
});

const startFunnelSessionSchema = z.object({
  step: startStepSchema,
  context: z
    .object({
      selectedDraftTemplate: selectedDraftTemplateSchema.nullable().optional(),
      prompt: z.string().optional(),
      promptState: promptStateSchema.optional(),
      hasUpload: z.boolean().optional(),
      selectedDocument: selectedDocumentSchema.nullable().optional(),
      referenceFileIds: z.array(z.string()).optional(),
      hasGeneratedSuggestions: z.boolean().optional(),
      images: z.array(imageItemSchema).optional(),
      theme: themeSchema.optional(),
      exportedProductId: publicIdSchema.nullable().optional()
    })
    .optional()
});

const START_FUNNEL_STORAGE_KEY = 'start-funnel-data';

const parseStartFunnelSession = (saved: string): StartFunnelSession | null => {
  try {
    const parsed = JSON.parse(saved);
    const result = startFunnelSessionSchema.safeParse(parsed);

    if (!result.success) {
      return null;
    }

    return result.data;
  } catch {
    return null;
  }
};

const getSessionStorage = () => {
  if (typeof window === 'undefined') {
    return null;
  }

  return window.sessionStorage;
};

export const readStartFunnelSession = (): StartFunnelSession | null => {
  const storage = getSessionStorage();
  if (!storage) return null;

  const saved = storage.getItem(START_FUNNEL_STORAGE_KEY);
  if (!saved) return null;

  return parseStartFunnelSession(saved);
};

export const writeStartFunnelSession = (session: StartFunnelSession) => {
  const storage = getSessionStorage();
  if (!storage) return;

  const serialized = JSON.stringify(session);
  if (storage.getItem(START_FUNNEL_STORAGE_KEY) === serialized) {
    return;
  }

  storage.setItem(START_FUNNEL_STORAGE_KEY, serialized);
};

export const clearStartFunnelSession = () => {
  const storage = getSessionStorage();
  if (!storage) return;

  storage.removeItem(START_FUNNEL_STORAGE_KEY);
};

export const normalizeStartFunnelSessionStorage =
  (): StartFunnelSession | null => {
    const storage = getSessionStorage();
    if (!storage) return null;

    const saved = storage.getItem(START_FUNNEL_STORAGE_KEY);
    if (!saved) return null;

    const session = parseStartFunnelSession(saved);
    if (!session) {
      storage.removeItem(START_FUNNEL_STORAGE_KEY);
      return null;
    }

    const normalized = JSON.stringify(session);
    if (saved !== normalized) {
      storage.setItem(START_FUNNEL_STORAGE_KEY, normalized);
    }

    return session;
  };

export const getStartPathByStep = (step: StartStepKey): string => {
  switch (step) {
    case 'prompt':
      return '/start/prompt';
    case 'upload':
      return '/start/upload';
    case 'visual-suggestions':
      return '/start/visual-suggestions';
    case 'settings':
      return '/start/settings';
    case 'generate':
      return '/start/generate';
    case 'template':
    default:
      return '/start/template';
  }
};
